begin;
set local search_path=public,extensions;
select plan(35);
select ok((select count(*)=11 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relkind='r'and c.relname=any(array['benefit_definitions','benefit_versions','box_definitions','box_versions','box_slots','plan_box_rules','customer_boxes','credit_lots','benefit_redemptions','credit_lot_movements','benefit_redemption_events'])),'eleven Boxes, benefits and credit records exist');
select ok((select count(*)=11 and bool_and(c.relrowsecurity)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname=any(array['benefit_definitions','benefit_versions','box_definitions','box_versions','box_slots','plan_box_rules','customer_boxes','credit_lots','benefit_redemptions','credit_lot_movements','benefit_redemption_events'])),'RLS covers the entire domain');
select ok((select count(*)=11 from pg_policies where schemaname='public'and tablename=any(array['benefit_definitions','benefit_versions','box_definitions','box_versions','box_slots','plan_box_rules','customer_boxes','credit_lots','benefit_redemptions','credit_lot_movements','benefit_redemption_events'])),'every domain table has an explicit read policy');
select ok(not exists(select 1 from information_schema.columns where table_schema='public'and table_name=any(array['benefit_versions','box_versions','credit_lots','benefit_redemptions'])and data_type in('real','double precision')),'credits and money never use floating point');
select ok((select count(*)>=7 from information_schema.columns where table_schema='public'and table_name=any(array['benefit_versions','box_versions','credit_lots'])and(column_name like'%_minor'or column_name like'%credit%')and data_type='bigint'),'credits and money use bigint exact units');
select ok((select count(*)=1 from pg_indexes where schemaname='public'and indexname='benefit_one_active_version_idx'),'only one active benefit version exists');
select ok((select count(*)=1 from pg_indexes where schemaname='public'and indexname='box_one_active_version_idx'),'only one active Box version exists');
select ok((select count(*)=8 from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname=any(array['benefit_versions','box_versions','box_slots','plan_box_rules','customer_boxes','credit_lots','credit_lot_movements','benefit_redemption_events'])and t.tgname like'%_immutable'and not t.tgisinternal),'versions, lots and histories are immutable');
select ok(not has_function_privilege('authenticated','public.append_credit_entry(uuid,uuid,text,bigint,text,text,text,text,uuid)','EXECUTE'),'legacy generic append is not a client API');
select ok(not has_function_privilege('anon','public.append_credit_entry(uuid,uuid,text,bigint,text,text,text,text,uuid)','EXECUTE'),'anonymous cannot append credits');
select ok((select count(*)=5 and bool_and(p.prosecdef and p.proconfig::text like'%search_path=%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['ensure_client_credit_wallet','issue_credits','reserve_benefit_credits','release_benefit_credits','consume_benefit_credits'])),'five hardened credit commands exist');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['ensure_client_credit_wallet','issue_credits','reserve_benefit_credits','release_benefit_credits','consume_benefit_credits'])and(has_function_privilege('anon',p.oid,'EXECUTE')or has_function_privilege('service_role',p.oid,'EXECUTE'))),'anonymous and service roles cannot execute credit commands');
select ok((select count(*)=5 and bool_and(has_function_privilege('authenticated',p.oid,'EXECUTE'))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['ensure_client_credit_wallet','issue_credits','reserve_benefit_credits','release_benefit_credits','consume_benefit_credits'])),'authenticated receives explicit command execution');
select ok(not has_table_privilege('authenticated','public.credit_wallets','INSERT')and not has_table_privilege('authenticated','public.credit_ledger_entries','INSERT')and not has_table_privilege('authenticated','public.credit_lots','INSERT')and not has_table_privilege('authenticated','public.benefit_redemptions','UPDATE'),'direct wallet, ledger, lot and redemption mutation is denied');
select ok((select pg_get_functiondef(p.oid)like'%credits_admin_access%'and pg_get_functiondef(p.oid)not like'%credits_client_access%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='issue_credits'),'only platform finance/admin can issue credits');
select ok((select pg_get_functiondef(p.oid)like'%ADMIN_GRANT%'and pg_get_functiondef(p.oid)like'%p_approval_reference%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='issue_credits'),'manual gifts require approval evidence');
select ok((select pg_get_functiondef(p.oid)like'%wallet_type=''CLIENT''%'and pg_get_functiondef(p.oid)like'%for update%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='issue_credits'),'issuance locks a client wallet');
select ok((select pg_get_functiondef(p.oid)like'%order by l.expires_at%'and pg_get_functiondef(p.oid)like'%for update of l%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='reserve_benefit_credits'),'reservation atomically allocates earliest-expiring lots first');
select ok((select pg_get_functiondef(p.oid)like'%l.library_id is null or l.library_id=b.library_id%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='reserve_benefit_credits'),'library-scoped promotional credits cannot cross domains');
select ok((select pg_get_functiondef(p.oid)like'%INSUFFICIENT_ELIGIBLE_CREDITS%'and pg_get_functiondef(p.oid)like'%entry_type,quantity%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='reserve_benefit_credits'),'reservation rejects insufficient eligible credits and writes the ledger');
select ok((select pg_get_functiondef(p.oid)like'%delivery_proof_hash%'and pg_get_functiondef(p.oid)like'%DELIVERY_PROVED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='consume_benefit_credits'),'consumption requires immutable delivery evidence');
select ok((select pg_get_functiondef(p.oid)like'%''RELEASE'',d.reserved_credits%'and pg_get_functiondef(p.oid)like'%''CONSUME'',-d.reserved_credits%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='consume_benefit_credits'),'reservation conversion does not debit the wallet twice');
select ok((select count(*)=5 and bool_and(pg_get_functiondef(p.oid)like'%begin_credit_command%'and pg_get_functiondef(p.oid)like'%finish_credit_command%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['ensure_client_credit_wallet','issue_credits','reserve_benefit_credits','release_benefit_credits','consume_benefit_credits'])),'all credit commands use canonical idempotence');
select ok((select count(*)=5 and bool_and(pg_get_functiondef(p.oid)like'%audit_events%'and pg_get_functiondef(p.oid)like'%event_outbox%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['ensure_client_credit_wallet','issue_credits','reserve_benefit_credits','release_benefit_credits','consume_benefit_credits'])),'all credit commands emit audit and Outbox evidence');
select ok((select count(*)=6 from pg_indexes where schemaname='public'and indexname=any(array['benefit_versions_active_idx','box_versions_active_idx','customer_boxes_org_period_idx','credit_lots_fifo_idx','redemptions_org_status_idx','lot_movements_redemption_idx'])),'operational indexes cover publication, tenant reads and FIFO');
select ok((select pg_get_functiondef(p.oid)like'%CLIENT_OWNER%'and pg_get_functiondef(p.oid)like'%CLIENT_ADMIN%'and pg_get_functiondef(p.oid)like'%CLIENT_ACCOUNTING%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='credits_client_access'),'client access is role-scoped');
select ok((select pg_get_functiondef(p.oid)like'%SUPER_ADMIN%'and pg_get_functiondef(p.oid)like'%FINANCE_MANAGER%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='credits_admin_access'),'issuance authority is platform-scoped');
select ok((select count(*)=1 from pg_constraint where conrelid='public.credit_lot_movements'::regclass and contype='u'and pg_get_constraintdef(oid)like'%credit_lot_id, redemption_id, movement_type%'),'lot movement replay is unique by transition');
select ok((select count(*)=1 from pg_constraint where conrelid='public.benefit_redemption_events'::regclass and contype='u'and pg_get_constraintdef(oid)like'%redemption_id, idempotency_key%'),'redemption transition replay is unique');
select ok((select pg_get_functiondef(p.oid)like'%organization_id=p_organization_id%'and pg_get_functiondef(p.oid)like'%wallet_type=''CLIENT''%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='reserve_benefit_credits'),'reservation binds tenant and wallet type');
select ok((select pg_get_functiondef(p.oid)like'%status=''ACTIVE''%'and pg_get_functiondef(p.oid)like'%effective_from<=clock_timestamp()%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='reserve_benefit_credits'),'only an active effective benefit version can be reserved');
select ok((select count(*)>=1 from pg_constraint where conrelid='public.box_versions'::regclass and contype='c'and pg_get_constraintdef(oid)like'%cost_full_minor <= cost_expected_minor%'and pg_get_constraintdef(oid)like'%approval_reference%'),'unprofitable Box publication requires approval evidence');
select ok((select count(*)=1 from pg_constraint where conrelid='public.credit_lots'::regclass and contype='c'and pg_get_constraintdef(oid)like'%expires_at > created_at%'),'credit lots require future expiry');
select ok((select p.prosecdef and p.proconfig::text like'%search_path=%'and has_function_privilege('authenticated',p.oid,'EXECUTE')and not has_function_privilege('anon',p.oid,'EXECUTE')and not has_function_privilege('service_role',p.oid,'EXECUTE')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='expire_credit_lot'),'lot expiry is a hardened authenticated command');
select ok((select pg_get_functiondef(p.oid)like'%credits_admin_access%'and pg_get_functiondef(p.oid)like'%CREDIT_LOT_NOT_EXPIRED%'and pg_get_functiondef(p.oid)like'%''EXPIRE'',-available%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='expire_credit_lot'),'only platform administration can expire the exact available lot remainder');
select * from finish();rollback;
